def solve(payload):
    chosen = {}
    as_of = payload.get('as_of', 0)
    for source, rows in enumerate((payload.get('base', []), payload.get('incoming', []))):
        for row in rows:
            if row.get('updated_at', 0) <= as_of:
                key = row.get('id')
                rank = (row.get('updated_at', 0), row.get('version', 0), source)
                if key not in chosen or rank > chosen[key][0]:
                    chosen[key] = (rank, row)
    records = []
    for key in sorted(chosen):
        row = chosen[key][1]
        if row.get('deleted'):
            continue
        value = dict(row.get('value', {}))
        value['tags'] = sorted(value.get('tags', []))
        records.append({'id': key, 'version': row.get('version'), 'updated_at': row.get('updated_at'), 'value': value})
    return {'records': records}

def solve(payload):
    chosen = {}
    as_of = payload.get('as_of', 0)
    for source, rows in enumerate((payload.get('base', []), payload.get('incoming', []))):
        for row in rows:
            if row.get('deleted') or row.get('updated_at', 0) > as_of:
                continue
            key = row.get('id')
            rank = (row.get('version', 0), row.get('updated_at', 0), source)
            if key not in chosen or rank > chosen[key][0]:
                chosen[key] = (rank, row)
    return {'records': [{'id': key, 'version': chosen[key][1].get('version'), 'updated_at': chosen[key][1].get('updated_at'), 'value': {'name': chosen[key][1].get('value', {}).get('name', ''), 'tags': sorted(chosen[key][1].get('value', {}).get('tags', []))}} for key in sorted(chosen)]}
